import pytest

from utils.exceptions import PokedexException
from utils.utils import get_state_and_country_codes_from_input


def test_common_name_country_resolves():
    state, country = get_state_and_country_codes_from_input(
        "", "South Korea", should_fail=False
    )
    assert country == "KR"


def test_iso_name_country_resolves():
    state, country = get_state_and_country_codes_from_input(
        "California", "United States"
    )
    assert state == "CA"
    assert country == "US"


def test_alpha_2_passes_through():
    state, country = get_state_and_country_codes_from_input("", "KR", should_fail=False)
    assert country == "KR"


def test_unknown_country_raises():
    with pytest.raises(PokedexException):
        get_state_and_country_codes_from_input("", "Southh Korea")

from utils.utils import (
    dt_to_str,
    get_request_session,
    get_country_code_3_from_input,
    get_state_and_country_codes_from_input,
    ts_to_str,
)

# a healthy fulfillor server answers the handshake in well under a second, so
# cap the wait instead of sitting on the operating system's multi-minute default
CONNECT_TIMEOUT_SECONDS = 10


class Integration(WMSIntegration):
    def test_account(self):
        # vendor exposes no per-shipment origin; warehouse address unavailable
        "ship_from_address": IntegrationNotImplemented,
        "packages": packages,
    }


def fulfillor_iso_to_str(raw):
    # vendor returns offset-aware ISO (e.g. +0530); utils.format_iso drops the
    # offset via its fractional-second strip, so parse directly to keep real UTC
    if not raw:
        return None
    return dt_to_str(datetime.fromisoformat(raw))

